chrome.action.onClicked.addListener(e=>{e.id&&chrome.sidePanel.open({windowId:e.windowId})});chrome.tabs.onUpdated.addListener(async(e,i,n)=>{i.status==="complete"&&n.url&&await chrome.sidePanel.setOptions({tabId:e,path:"sidepanel.html",enabled:!0})});chrome.runtime.onMessage.addListener((e,i,n)=>{e.type==="INSERT_EMOJI"&&chrome.tabs.query({active:!0,currentWindow:!0},d=>{d[0]&&d[0].id&&chrome.tabs.sendMessage(d[0].id,{type:"INSERT_EMOJI",emoji:e.emoji})})});
